const assert = require("assert");
const { siraylaIsle, tekrarDene, say, ortalama, grupla } = require("./islem.js");

(async () => {
  // siraylaIsle: sıralı çağrı — gecikme sırası farklı olsa bile çağrı sırası korunmalı
  const order = [];
  const r = await siraylaIsle([1, 2, 3], async (x) => {
    order.push("start" + x);
    await new Promise(res => setTimeout(res, x === 1 ? 50 : 5));
    order.push("end" + x);
    return x * 10;
  });
  assert.deepStrictEqual(r, [10, 20, 30]);
  assert.deepStrictEqual(order, ["start1", "end1", "start2", "end2", "start3", "end3"]);

  // tekrarDene: tam deneme kez çağrılır, ilk başarılı sonucu döner
  let n = 0;
  const res = await tekrarDene(async (i) => { n++; if (i < 2) throw new Error("h" + i); return "ok" + i; }, 3);
  assert.strictEqual(res, "ok2");
  assert.strictEqual(n, 3);

  // tekrarDene: hepsi başarısızsa SON hatayı fırlatır; deneme=3 ise tam 3 kez
  n = 0;
  try {
    await tekrarDene(async (i) => { n++; throw new Error("err" + i); }, 3);
    assert.fail("hata fırlatılmalıydı");
  } catch (e) {
    assert.strictEqual(e.message, "err2");
  }
  assert.strictEqual(n, 3);

  // tekrarDene: ilk denemede başarı
  n = 0;
  const res2 = await tekrarDene(async (i) => { n++; return 42; });
  assert.strictEqual(res2, 42);
  assert.strictEqual(n, 1);

  // say
  assert.deepStrictEqual(say(["a", "b", "a"]), { a: 2, b: 1 });
  assert.deepStrictEqual(say([1, 1, 1]), { 1: 3 });
  assert.deepStrictEqual(say([]), {});

  // ortalama
  assert.strictEqual(ortalama([]), 0);
  assert.strictEqual(ortalama([2, 4]), 3);
  assert.strictEqual(ortalama([5]), 5);

  // grupla: öğe sırası korunur
  const g = grupla([1, 2, 3, 4, 5, 6], x => x % 2);
  assert.deepStrictEqual(g, { 1: [1, 3, 5], 0: [2, 4, 6] });

  console.log("EK TESTLER GEÇTİ");
})().catch((e) => { console.error("BASARISIZ:", e.message); process.exit(1); });

